CREATE COLUMN TABLE "TEST_AP"."OBOS" ("AbsEntry" INTEGER CS_INT NOT NULL , "IsUsed" NVARCHAR(1) DEFAULT 'N', "EffecDate" LONGDATE CS_LONGDATE NOT NULL , "FileFmtCo" INTEGER CS_INT, "IsDeleted" NVARCHAR(1) DEFAULT 'N', "ReportType" NVARCHAR(1) DEFAULT 'S' NOT NULL , PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OBOS_EFFEC_DATE" ON "TEST_AP"."OBOS" ( "EffecDate" ASC );
CREATE UNIQUE INDEX "OBOS_BZKEY" ON "TEST_AP"."OBOS" ( "EffecDate" ASC, "ReportType" ASC )